                ["وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ"],["وَمَن يُكْرِههُّنَّ فَإِنَّ اللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ"],["فَكَفَرُوا۟ وَتَوَلَّوا۟ وَاسْتَغْنَى اللَّهُ"],["ذَٰلِكَ بِمَا عَصَوا۟ وَكَانُوا۟ يَعْتَدُونَ"],["ثُمَّ اتَّقَوا۟ وَءَامَنُوا۟ ثُمَّ اتَّقَوا۟ وَأَحْسَنُوا۟"],["تِلْكَ عُقْبَى الَّذِينَ اتَّقَوا۟ وَعُقْبَى الْكَٰفِرِينَ النَّارُ"],["بَسَطتَ إِلَىَّ", "فَقَالَ أَحَطتُ" ,"مَا فَرَّطتُمْ"],["يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ اللَّهِ"]
